draft:
version: tapstate/v1
kind: pipeline
id: product_state_ai
metadata:
  description: >-
    One document per product (PLM), with its prices (costing), its stock by
    location (WMS) and its suppliers with their terms (procurement).
source: [src_mfg_plm, src_mfg_costing, src_mfg_wms, src_mfg_procurement]

transforms:
  # ---- prices (costing): decimals to numbers ---------------------------------
  - id: t_prices
    type: js
    from: [item_prices]
    script: |
      function process(record, ctx) {
        if (record.before != null) fix(record.before);
        fix(record.after);
        return record;
      }
      function fix(r) {
        if (r != null) { r.standard_cost = num(r.standard_cost); r.list_price = num(r.list_price); }
      }
      function num(v) { return v == null ? null : Number(v); }

  - id: t_list_hist
    type: js
    from: [list_price_history]
    script: |
      function process(record, ctx) {
        if (record.before != null) fix(record.before);
        fix(record.after);
        return record;
      }
      function fix(r) { if (r != null) r.list_price = r.list_price == null ? null : Number(r.list_price); }

  - id: t_cost_hist
    type: js
    from: [standard_cost_history]
    script: |
      function process(record, ctx) {
        if (record.before != null) fix(record.before);
        fix(record.after);
        return record;
      }
      function fix(r) { if (r != null) r.standard_cost = r.standard_cost == null ? null : Number(r.standard_cost); }

  # ---- inventory (WMS): item is 'AW:' + product number ----------------------
  - id: t_stock
    type: js
    from: [stock]
    script: |
      function process(record, ctx) {
        // the before image too: a delete carries only that, and the nest needs its join key
        if (record.before != null) fix(record.before);
        fix(record.after);
        return record;
      }
      function fix(r) {
        if (r != null) {
          var s = String(r.item);
          r.product_number = s.indexOf('AW:') === 0 ? s.substring(3) : s;
          r.stock_id = r._id;
        }
      }

  - id: t_loc
    type: js
    from: [locations]
    script: |
      function process(record, ctx) {
        if (record.before != null) fix(record.before);
        fix(record.after);
        return record;
      }
      function fix(r) { if (r != null) r.location_id = r._id; }

  # ---- suppliers (procurement): part_ref writes '_' where PLM writes '-' -----
  - id: t_offer
    type: js
    from: [vendor_items]
    script: |
      function process(record, ctx) {
        if (record.before != null) fix(record.before);
        fix(record.after);
        return record;
      }
      function fix(r) {
        if (r != null) {
          r.product_number = String(r.part_ref).split('_').join('-');
          r.offer_id = r.part_ref + '/' + r.vendor_id;
          r.standard_price = r.standard_price == null ? null : Number(r.standard_price);
          r.last_receipt_cost = r.last_receipt_cost == null ? null : Number(r.last_receipt_cost);
        }
      }

  # ---- one product document --------------------------------------------------
  - id: assemble
    type: nest
    from: {p: products, ip: t_prices, lh: t_list_hist, ch: t_cost_hist,
           st: t_stock, lo: t_loc, of: t_offer, ve: vendors}
    entries_in_memory: 250000
    root:
      from: p
      key: [product_number]
      embed:
        - {from: ip, on: {product_number: product_number}, as: object, path: prices, key: [product_number]}
        - {from: lh, on: {product_number: product_number}, as: array, path: list_price_history, arrayKey: [start_date]}
        - {from: ch, on: {product_number: product_number}, as: array, path: standard_cost_history, arrayKey: [start_date]}
        - from: st
          on: {product_number: product_number}
          as: array
          path: inventory
          arrayKey: [stock_id]
          embed:
            - {from: lo, on: {location_id: location_id}, as: object, path: location, key: [location_id]}
        - from: of
          on: {product_number: product_number}
          as: array
          path: suppliers
          arrayKey: [offer_id]
          embed:
            - {from: ve, on: {vendor_id: vendor_id}, as: object, path: vendor, key: [vendor_id]}

  - id: shape
    type: js
    from: [assemble]
    script: |
      function only(r, keys) { var o = {}; keys.forEach(function (k) { o[k] = r[k] == null ? null : r[k]; }); return o; }
      function process(record, ctx) {
        var r = record.after;
        if (r == null) return record;
        var ip = r.prices || {};
        var doc = only(r, ['product_number', 'name', 'make_flag', 'finished_goods_flag', 'color', 'size',
                           'size_unit_measure_code', 'weight', 'weight_unit_measure_code', 'product_line',
                           'class', 'style', 'safety_stock_level', 'reorder_point', 'days_to_manufacture',
                           'sell_start_date', 'sell_end_date', 'discontinued_date']);
        doc.weight = doc.weight == null ? null : Number(doc.weight);
        doc.price = {
          list_price: ip.list_price == null ? null : ip.list_price,
          standard_cost: ip.standard_cost == null ? null : ip.standard_cost,
          list_price_history: (r.list_price_history || []).map(function (h) {
            return only(h, ['start_date', 'end_date', 'list_price']); }),
          standard_cost_history: (r.standard_cost_history || []).map(function (h) {
            return only(h, ['start_date', 'end_date', 'standard_cost']); })
        };
        var total = 0;
        var locs = (r.inventory || []).map(function (i) {
          var l = i.location;
          if (i.quantity != null) total += i.quantity;
          var o = { stock_id: i.stock_id,
                    location: { location_id: i.location_id, name: l == null ? null : l.name } };
          ['shelf', 'bin', 'quantity'].forEach(function (k) { o[k] = i[k] == null ? null : i[k]; });
          return o; });
        doc.inventory = { total_quantity: total, below_safety_stock:
                            r.safety_stock_level == null ? null : total < r.safety_stock_level,
                          locations: locs };
        doc.suppliers = (r.suppliers || []).map(function (s) {
          var v = s.vendor;
          var o = only(s, ['average_lead_time', 'standard_price', 'last_receipt_cost', 'last_receipt_date',
                           'min_order_qty', 'max_order_qty', 'on_order_qty', 'unit_measure_code']);
          o.vendor = v == null ? { vendor_id: s.vendor_id } :
            only(v, ['vendor_id', 'account_number', 'name', 'credit_rating', 'preferred_vendor_status',
                     'active_flag']);
          return o; });
        record.after = doc;
        return record;
      }

view:
  id: product_state_ai
  from: shape
  primary_key: product_number
